import 'dart:ui'; import 'package:flutter/material.dart'; import 'package:google_fonts/google_fonts.dart';  class PreferencesScreen extends StatefulWidget {   const PreferencesScreen({super.key});    @override   State<PreferencesScreen> createState() => _PreferencesScreenState(); }  class _PreferencesScreenState extends State<PreferencesScreen>     with SingleTickerProviderStateMixin {   int _currentScreen = 0;   String _name = '';   List<int?> _selections = [null, null, null, null, null];   bool _isForward = true;    late AnimationController _mascotController;   late Animation<double> _mascotAnimation;    @override   void initState() {     super.initState();     _mascotController = AnimationController(       vsync: this,       duration: const Duration(seconds: 3),     )..repeat(reverse: true);     _mascotAnimation = Tween<double>(begin: 0, end: -8).animate(       CurvedAnimation(parent: _mascotController, curve: Curves.easeInOut),     );   }    @override   void dispose() {     _mascotController.dispose();     super.dispose();   }    bool get _canContinue {     if (_currentScreen == 0) {       return _name.trim().isNotEmpty;     }     return _selections[_currentScreen] != null;   }    void _goBack() {     if (_currentScreen > 0) {       setState(() {         _isForward = false;         _currentScreen--;       });     }   }    void _goForward() {     if (_canContinue) {       if (_currentScreen < 4) {         setState(() {           _isForward = true;           _currentScreen++;         });       } else {         Navigator.pushReplacementNamed(context, '/home');       }     }   }    @override   Widget build(BuildContext context) {     return Scaffold(       resizeToAvoidBottomInset: false,       body: Stack(         children: [           // Background           Positioned.fill(             child: Image.asset(               'assets/images/bg.jfif',               fit: BoxFit.cover,             ),           ),                      SafeArea(             child: Column(               children: [                 _buildHeader(),                 Expanded(                   child: AnimatedSwitcher(                     duration: const Duration(milliseconds: 400),                     switchInCurve: Curves.easeOutCubic,                     switchOutCurve: Curves.easeInCubic,                     transitionBuilder: (Widget child, Animation<double> animation) {                       final inAnimation = Tween<Offset>(                         begin: Offset(_isForward ? 0.15 : -0.15, 0),                         end: Offset.zero,                       ).animate(animation);                       final outAnimation = Tween<Offset>(                         begin: Offset(_isForward ? -0.15 : 0.15, 0),                         end: Offset.zero,                       ).animate(animation);                        return SlideTransition(                         position: child.key == ValueKey(_currentScreen) ? inAnimation : outAnimation,                         child: FadeTransition(                           opacity: animation,                           child: child,                         ),                       );                     },                     child: Container(                       key: ValueKey(_currentScreen),                       width: double.infinity,                       padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 16),                       child: _buildCurrentScreen(),                     ),                   ),                 ),                 const SizedBox(height: 100), // Space for sticky button               ],             ),           ),            // Sticky Continue Button           Positioned(             bottom: 24,             left: 24,             right: 24,             child: _buildContinueButton(),           ),         ],       ),     );   }    Widget _buildHeader() {     return Padding(       padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 16),       child: Row(         children: [ 