0),             width: 2,           ),         ),         child: Center(           child: Text(             'CONTINUE',             style: GoogleFonts.poppins(               fontSize: 16,               fontWeight: FontWeight.bold,               letterSpacing: 0.8,               color: isEnabled ? const Color(0xFFE07B39) : const Color(0xFF9E968B),             ),           ),         ),       ),     );   }    Widget _buildCurrentScreen() {     switch (_currentScreen) {       case 0: return _buildScreen0();       case 1: return _buildScreen1();       case 2: return _buildScreen2();       case 3: return _buildScreen3();       case 4: return _buildScreen4();       default: return const SizedBox.shrink();     }   }    Widget _buildMascot(String asset) {     return SizedBox(       width: 70,       height: 70,       child: AnimatedBuilder(         animation: _mascotAnimation,         builder: (context, child) {           return Transform.translate(             offset: Offset(0, _mascotAnimation.value),             child: child,           );         },         child: Image.asset(asset, fit: BoxFit.contain),       ),     );   }    Widget _buildScreen0() {     return Column(       crossAxisAlignment: CrossAxisAlignment.start,       children: [         Row(           crossAxisAlignment: CrossAxisAlignment.start,           children: [             _buildMascot('assets/images/mascot.png'),             const SizedBox(width: 16),             Expanded(               child: _SpeechBubble(                 child: RichText(                   text: TextSpan(                     style: GoogleFonts.poppins(                       fontSize: 16,                       color: const Color(0xFF38322E),                     ),                     children: [                       const TextSpan(text: 'Welcome to '),                       TextSpan(                         text: 'DharmaPath',                         style: GoogleFonts.poppins(                           fontWeight: FontWeight.bold,    