 borderRadius: BorderRadius.circular(18),           border: const Border(             top: BorderSide(color: Color(0xFFCFCAC0), width: 2),             left: BorderSide(color: Color(0xFFCFCAC0), width: 2),             right: BorderSide(color: Color(0xFFCFCAC0), width: 2),             bottom: BorderSide(color: Color(0xFFCFCAC0), width: 4),           ),         ),         child: ClipRRect(           borderRadius: BorderRadius.circular(18),           child: BackdropFilter(             filter: ImageFilter.blur(sigmaX: 8, sigmaY: 8),             child: Padding(               padding: const EdgeInsets.all(16.0),               child: child,             ),           ),         ),       ),     );   } }  class _SpeechBubblePainter extends CustomPainter {   @override   void paint(Canvas canvas, Size size) {     final paint = Paint()       ..color = const Color(0xFFCFCAC0)       ..style = PaintingStyle.fill;      // Draw the triangle pointer pointing left     final path = Path();     path.moveTo(12, size.height / 2 - 8);     path.lineTo(2, size.height / 2);     path.lineTo(12, size.height / 2 + 8);     path.close();      canvas.drawPath(path, paint);   }    @override   bool shouldRepaint(covariant CustomPainter oldDelegate) => false; }  class _ChoiceCard extends StatelessWidget {   final String icon;   final String label;   final String? subtitle;   final String? badge;   final bool isSelected;   final VoidCallback onTap;    const _ChoiceCard({     required this.icon,     required this.label,     this.subtitle,     this.badge,     required this.isSelected,     required this.onTap,   });    @override   Widget build(BuildContext context) {     return GestureDetector(       onTap: onTap,       child: AnimatedContainer(         duration: const Duration(milliseconds: 300),         padding: const EdgeInsets.all(16),         decoration: BoxDecoration(           color: isSelected ? const Color(0x40FFF5EE) : const Color(0x26FFFFFF),           borderRadius: BorderRadius.circular(16),     