eInsets.symmetric(horizontal: 10, vertical: 6),                     decoration: BoxDecoration(                       color: isSelected ? const Color(0xFFE07B39) : const Color(0xFFCFCAC0),                       borderRadius: BorderRadius.circular(20),                     ),                     child: Text(                       badge!,                       style: GoogleFonts.poppins(                         fontSize: 11,                         fontWeight: FontWeight.bold,                         color: isSelected ? Colors.white : const Color(0xFF38322E),                       ),                     ),                   ),               ],             ),           ),         ),       ),     );   } }